return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : (((n == 1)) && ((0 == 0))) ? 0 : 2);','language'=>'it_IT','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Esegue il backup dei tuoi file e del database di WordPress sul tuo spazio di archiviazione — Dropbox, Google Drive, Cloudflare R2, Amazon S3 o qualsiasi bucket compatibile con S3 —, li ripristina in una volta sola e importa i backup creati da altri plugin di backup e migrazione.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Backup','Get Pro: schedules, several storages, encryption'=>'Passa a Pro: pianificazioni, più posizioni di archiviazione, crittografia','Working…'=>'In corso…','Finished'=>'Completato','Failed'=>'Non riuscito','Cancelled'=>'Annullato','Cancel'=>'Annulla','Restore'=>'Ripristina','Delete'=>'Elimina','Delete this backup from your storage? This cannot be undone.'=>'Vuoi eliminare questo backup dal tuo spazio di archiviazione? Questa azione non può essere annullata.','No backups yet. Press “Back up now” to make the first one.'=>'Nessun backup disponibile. Premi "Esegui il backup ora" per creare il primo.','Reading your storage…'=>'Lettura del tuo spazio di archiviazione in corso…','a complete backup, as opposed to an incremental oneFull backup'=>'Backup completo','a backup holding only what changed since an earlier oneIncremental backup'=>'Backup incrementale','Encrypted'=>'Crittografato','From another site'=>'Da un altro sito','Database'=>'Database','Files'=>'File','Uploading %1$s: %2$s%%'=>'Caricamento di %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Accedi a Dropbox nella finestra che si è aperta, quindi incolla il codice mostrato da Dropbox:','Saved.'=>'Salvato.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Rimuovere questa destinazione dal plugin? I backup memorizzati al suo interno non vengono eliminati.','Reload the page to see the restored site.'=>'Ricarica la pagina per visualizzare il sito ripristinato.','Storage'=>'Spazio di archiviazione','Import & migrate'=>'Importa e migra','Settings'=>'Impostazioni','Sections'=>'Sezioni','Google Drive is connected.'=>'Google Drive è connesso.','Google Drive could not be connected.'=>'Impossibile connettere Google Drive.','Details'=>'Dettagli','Back up now'=>'Esegui il backup adesso','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'I backup vengono salvati nel tuo spazio di archiviazione, non su questo server. Prima di tutto <a href="%s">collega il tuo spazio di archiviazione</a>.','What to back up'=>'Cosa includere nel backup','Files and database'=>'File e database','Database only'=>'Solo database','Files only'=>'Solo file','Note (optional)'=>'Nota (facoltativo)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Ogni parte viene caricata sul tuo spazio di archiviazione e rimossa da questo server prima che venga creata la successiva, quindi il backup non occupa mai spazio sul tuo hosting.','Your backups'=>'I tuoi backup','Refresh'=>'Aggiorna','Restore this backup'=>'Ripristina questo backup','Passphrase'=>'Passphrase','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Ho compreso che questo sostituisce i file e il database di questo sito con quelli del backup. I file che non sono presenti nel backup vengono mantenuti.','Recent activity'=>'Attività recente','Backup'=>'Backup','Restore / import'=>'Ripristina / importa','Running'=>'In esecuzione','Your storage'=>'Il tuo spazio di archiviazione' . "\0" . 'Le tue destinazioni di archiviazione' . "\0" . 'Le tue destinazioni di archiviazione','No storage yet. Choose where your backups go below.'=>'Nessuno spazio di archiviazione per ora. Scegli qui sotto dove andranno i tuoi backup.','Ready'=>'Pronto','Not connected'=>'Non connesso','Connect'=>'Connetti','Test'=>'Testa','Edit'=>'Modifica','Remove'=>'Rimuovi','Add storage'=>'Aggiungi spazio di archiviazione','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'I backup vanno a una destinazione di archiviazione. Per usarne una diversa, modifica o rimuovi quella sopra.','Kind of storage'=>'Tipo di archiviazione','Name (for you)'=>'Nome (per te)','Provider'=>'Fornitore','Cloudflare account id'=>'ID account Cloudflare','Endpoint address'=>'Indirizzo dell\'endpoint','Region'=>'Regione','Bucket'=>'Bucket','Access key id'=>'ID chiave di accesso','Secret access key'=>'Chiave di accesso segreta','Leave empty to keep the saved key'=>'Lascia vuoto per mantenere la chiave salvata','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Per Cloudflare R2: nella bacheca di Cloudflare apri R2, crea un bucket, poi “Manage R2 API tokens” → crea un token con Object Read & Write per quel bucket e copia qui l\'access key id e il secret.','Dropbox app key'=>'Chiave dell\'app Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Crea un\'app su dropbox.com/developers/apps (Scoped access, App folder) con i permessi files.content.read, files.content.write e files.metadata.read e copia la sua App key qui. Salva, quindi premi Connect.','OAuth client id'=>'ID client OAuth','OAuth client secret'=>'Segreto client OAuth','Leave empty to keep the saved secret'=>'Lascia vuoto per mantenere il segreto salvato','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'In Google Cloud Console, abilita l\'API Google Drive API, quindi crea un client OAuth di tipo "Web application" con questo indirizzo come URI di reindirizzamento autorizzato:','Save, then press Connect. The plugin only sees the files it creates.'=>'Salva, poi premi Connetti. Il plugin vede solo i file che crea.','Folder inside the storage (optional)'=>'Cartella all\'interno dello spazio di archiviazione (facoltativo)','Save storage'=>'Risparmia spazio di archiviazione','Import a backup from another plugin or host'=>'Importa un backup da un altro plugin o host','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Importa un sito da un backup creato da UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate o da qualsiasi archivio zip/tar di un sito WordPress con il relativo dump .sql. Il contenuto viene inserito in wp-content e il database sostituisce quello di questo sito; gli indirizzi vengono modificati automaticamente in quelli di questo sito.','Upload from your computer'=>'Carica dal tuo computer','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Scegli tutti i file del backup in una sola volta (UpdraftPlus ne crea diversi). I file di grandi dimensioni vengono inviati in piccole parti, quindi il limite di caricamento del tuo host non viene applicato.','Or from links (Google Drive, Dropbox or any download address)'=>'Oppure da link (Google Drive, Dropbox o qualsiasi indirizzo di download)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Un link per riga. Per Google Drive e Dropbox, condividi il file con "chiunque abbia il link" e incolla quel link; disattiva nuovamente la condivisione in seguito.','Or a file already on this server'=>'Oppure un file già presente su questo server','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Carica gli archivi tramite FTP o il file manager del tuo hosting in %s e ricarica questa pagina.','Or a deploy code from another site'=>'Oppure un codice di distribuzione da un altro sito','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Se un altro sito ti ha fornito un codice di deploy di Zinn® Backups, incollalo qui per copiare quel backup su questo sito senza condividere le relative chiavi di archiviazione. Il codice è valido per poche ore; trattalo come una password.','Passphrase (only if that backup is encrypted)'=>'Passphrase (solo se quel backup è crittografato)','Import'=>'Importa','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Ho compreso che l\'importazione sostituisce i contenuti e il database di questo sito. Successivamente, accedi con un account del sito importato.','Moving to Zinn® hosting?'=>'Stai passando all\'hosting Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® può trasferire il tuo sito dal tuo vecchio hosting per te. Se il tuo vecchio hosting non ti fornisce l\'accesso FTP, SSH o al pannello di controllo, installa Zinn® Migrate sul vecchio sito; crea un unico archivio che puoi importare qui o consegnare a Zinn®.','What goes into a backup'=>'Cosa è incluso in un backup','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Includi i file propri di WordPress (wp-admin, wp-includes). Di solito non è necessario: WordPress può essere sempre reinstallato.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Escludi anche queste cartelle o file (uno per riga, relativo alla cartella di WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Sempre esclusi: cache, spazio temporaneo per gli aggiornamenti e le cartelle di archivio di altri plugin di backup:','Size of each part (MB)'=>'Dimensione di ciascuna parte (MB)','Save settings'=>'Salva impostazioni','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Impossibile aprire una parte del backup per la scrittura. Verifica che wp-content abbia spazio libero.','A backup part could not be written. Check that wp-content has free space.'=>'Impossibile scrivere una parte del backup. Verifica che wp-content disponga di spazio libero.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Collega prima una destinazione di archiviazione nella scheda Storage: i backup vengono conservati nel tuo spazio di archiviazione, non su questo server.','Multisite networks are not supported yet.'=>'Le reti multisito non sono ancora supportate.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'Il PHP di questo server non ha l\'estensione ZipArchive. Chiedi al tuo host di abilitarla.','Starting'=>'Avvio in corso','Listing files'=>'Elenco dei file in corso','Backing up the database'=>'Backup del database in corso','Packing files'=>'Compressione dei file in corso','Uploading to your storage'=>'Caricamento nel tuo spazio di archiviazione','Finishing'=>'Completamento in corso','The backup reached an unknown stage.'=>'Il backup ha raggiunto una fase sconosciuta.','Backup %s started.'=>'Backup di %s avviato.','Found %1$s files (%2$s).'=>'Trovati %1$s file (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Database: %1$d tabelle, %2$s righe, %3$s compresso.','Backup complete: %1$s stored in %2$d destination.'=>'Backup completato: %1$s archiviato in %2$d destinazione.' . "\0" . 'Backup completato: %1$s memorizzato in %2$d destinazioni.' . "\0" . 'Backup completato: %1$s memorizzato in %2$d destinazioni.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Non è stato possibile rimuovere dal tuo spazio di archiviazione alcune parti già caricate; si trovano in una cartella di backup incompleta e non verranno mai proposte per il ripristino.','A storage destination was removed while the backup was running.'=>'Una destinazione di archiviazione è stata rimossa durante l\'esecuzione del backup.','That is not a backup folder.'=>'Quella non è una cartella di backup.','That storage destination is no longer saved on this site.'=>'Quella destinazione di archiviazione non è più salvata su questo sito.','Later incremental backups are built on this one. Delete those first.'=>'I backup incrementali successivi si basano su questo. Elimina prima quelli.','This file is not an encrypted Zinn® Backups file.'=>'Questo file non è un file Zinn® Backups crittografato.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Impossibile decifrare il backup: la passphrase è errata o il file è danneggiato.','The encrypted backup file is incomplete.'=>'Il file di backup crittografato è incompleto.','The database file could not be written. Check that wp-content has free space.'=>'Impossibile scrivere il file del database. Verifica che wp-content abbia spazio libero.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Questo non è un codice di distribuzione. Un codice di distribuzione inizia con zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Quel codice di distribuzione è danneggiato. Copialo di nuovo dall\'altro sito.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Il codice di distribuzione è scaduto o il relativo backup è stato eliminato. Crea un nuovo codice sull\'altro sito.','That deploy code does not point at a Zinn® Backups backup.'=>'Quel codice di distribuzione non punta a un backup di Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Il codice di distribuzione è scaduto. Crea un nuovo codice sull\'altro sito.','The server stopped honouring partial downloads. Start the import again.'=>'Il server ha smesso di supportare i download parziali. Riavvia l\'importazione.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Il link ha aperto una pagina web invece di un file. Per Google Drive e Dropbox, condividi il file con "chiunque abbia il link" e incolla quel link.','The link answered with HTTP %d.'=>'Il link ha risposto con HTTP %d.','The file list could not be written.'=>'Impossibile scrivere l\'elenco dei file.','The storage service could not be reached: %s'=>'Impossibile raggiungere il servizio di archiviazione: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ha risposto con HTTP %2$d: %3$s','no details given'=>'Nessun dettaglio fornito','You are not allowed to manage backups.'=>'Non hai il permesso di gestire i backup.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Seleziona la casella per confermare che il ripristino sostituisce i file e il database di questo sito.','Save the destination first.'=>'Salva prima la destinazione.','Connected: a test file was written and removed.'=>'Connesso: un file di test è stato scritto e rimosso.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Inserisci prima l\'app key della tua applicazione Dropbox (vedi i passaggi accanto al modulo).','This kind of storage does not sign in.'=>'Questo tipo di archiviazione non esegue l\'accesso.','The sign-in expired. Press Connect again.'=>'L\'accesso è scaduto. Premi nuovamente Connetti.','Dropbox is connected.'=>'Dropbox è connesso.','Settings saved.'=>'Impostazioni salvate.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Un altro backup, ripristino o importazione è in corso. Attendi che finisca oppure annullalo.','The upload was not started properly. Start again.'=>'Il caricamento non è stato avviato correttamente. Ricomincia.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Il frammento non è arrivato. Il tuo server potrebbe limitare le dimensioni di caricamento; riprova.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Seleziona la casella per confermare che l\'importazione sostituisce i contenuti e il database di questo sito.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Scegli un archivio da importare: caricalo, incolla un link o scegline uno dalla cartella di importazione.','Hosting customer? Get %1$d%% off %2$s'=>'Sei cliente hosting? Ricevi il %1$d%% di sconto su %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Come cliente di hosting Zinn Digital®, ricevi un codice personale per avere il %d%% di sconto sul tuo primo pagamento. I rinnovi sono al prezzo normale.','Get my %d%% code and go to checkout'=>'Ricevi il mio codice del %d%% e vai alla cassa','Sorry, you are not allowed to do that.'=>'Spiacenti, non hai il permesso di farlo.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Questo sconto è riservato ai clienti con un piano di hosting a pagamento in regola. Le prove gratuite non sono idonee.','You have already used your hosting-customer discount for this plugin.'=>'Hai già utilizzato il tuo sconto cliente hosting per questo plugin.','We could not get your code just now. Please try again in a few minutes.'=>'Non siamo riusciti a recuperare il tuo codice in questo momento. Riprova tra qualche minuto.','Reading the backup'=>'Lettura del backup in corso','Downloading the archive'=>'Download dell\'archivio in corso','Recognising the archive'=>'Riconoscimento dell\'archivio in corso','Restoring files'=>'Ripristino dei file','Downloading the database'=>'Download del database in corso','Restoring the database'=>'Ripristino del database','Updating the site address'=>'Aggiornamento dell\'indirizzo del sito','Switching to the restored database'=>'Passaggio al database ripristinato','The restore reached an unknown stage.'=>'Il ripristino ha raggiunto una fase sconosciuta.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Questa cartella non contiene un backup completo di Zinn® Backups (manca il manifest).','This backup is encrypted. Enter its passphrase to restore it.'=>'Questo backup è crittografato. Inserisci la sua passphrase per ripristinarlo.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Questo backup incrementale richiede il backup %s, che non è più presente nello spazio di archiviazione.','Restoring the backup of %1$s (%2$d file parts).'=>'Ripristino del backup di %1$s (%2$d parti del file).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Impossibile sovrascrivere il file %1$s perché questo sito non è autorizzato a modificarlo, ed è stato lasciato così com\'è: %2$s' . "\0" . 'Non è stato possibile sovrascrivere %1$s file perché questo sito non è autorizzato a modificarli, e sono stati lasciati invariati: %2$s' . "\0" . 'Non è stato possibile sovrascrivere %1$s file perché questo sito non è autorizzato a modificarli, e sono stati lasciati invariati: %2$s','Restored %s files.'=>'%s file ripristinati.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s non corrisponde al suo checksum dopo il download. La copia presente nell\'archivio potrebbe essere danneggiata.','%s did not arrive. Upload it again.'=>'%s non è arrivato. Caricalo di nuovo.','Recognised: %s.'=>'Riconosciuto: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Importati %1$s file in wp-content (%2$s tralasciati: cache, drop-in e cartelle di altri plugin di backup).','The archive has no database dump, so only files were imported.'=>'L\'archivio non contiene un dump del database, quindi sono stati importati solo i file.','Database restored into %d temporary tables.'=>'Database ripristinato in %d tabelle temporanee.','%s has no WordPress tables in it and was skipped.'=>'%s non contiene tabelle di WordPress ed è stato ignorato.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Il database del backup non contiene tabelle di WordPress, quindi non è stato sostituito nulla.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Questo backup appartiene a una rete multisito. Il ripristino di una rete in un singolo sito non è supportato.','Moving the content from %1$s to %2$s.'=>'Spostamento del contenuto da %1$s a %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Ripristino completato. Se ti sei disconnesso, accedi con un account del sito ripristinato.','Restore complete.'=>'Ripristino completato.','%1$s — trying again in %2$d seconds.'=>'%1$s — nuovo tentativo tra %2$d secondi.','Cancelled.'=>'Annullato.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'I backup vanno verso una sola destinazione di archiviazione. Modifica o rimuovi quella attuale per usarne una diversa.','The database file could not be opened.'=>'Impossibile aprire il file del database.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Il database ha rifiutato un\'istruzione dal backup: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Impossibile scambiare le tabelle ripristinate: %s. Il tuo sito è rimasto invariato.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Non è presente alcuna cartella scrivibile per i file di backup temporanei. Rendi scrivibile wp-content e riprova.','Could not create a folder for this job.'=>'Impossibile creare una cartella per questo processo.','%s — guides and services'=>'%s — guide e servizi','User guides'=>'Guide per l\'utente','Read the %s user guide'=>'Leggi la guida per l\'utente di %s','Hide this'=>'Nascondi questo','Zinn® hosting for WordPress'=>'Hosting Zinn® per WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, backup giornalieri, migrazione gratuita e un pannello di controllo creato per chi gestisce più di un sito.','The Zinn® marketplace'=>'Il marketplace di Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Compra e vendi siti avviati, domini e posizionamenti di link, con il denaro custodito al sicuro finché entrambe le parti non sono soddisfatte.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — assumi persone che lo fanno di mestiere','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Il nostro marketplace freelance globale: esplora oltre 10.000 servizi pronti offerti da scrittori, designer, sviluppatori ed esperti SEO, oppure pubblica un progetto e lascia che facciano un\'offerta.','See the Zinn Digital® release notes.'=>'Consulta le note di rilascio di Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Il servizio di aggiornamento Zinn® non ha fornito un link di scaricamento per questo aggiornamento. Verifica che questo sito possa raggiungere la piattaforma Zinn®, quindi riprova.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Impossibile scaricare l\'aggiornamento dal servizio di aggiornamento Zinn® (%s). Riprova tra qualche minuto.','The downloaded update failed its integrity check and was not installed.'=>'L\'aggiornamento scaricato non ha superato il controllo di integrità e non è stato installato.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Impossibile aprire l\'archivio zip. Potrebbe essere danneggiato o incompleto.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Questo file .wpress usa un formato che non possiamo leggere (potrebbe essere compresso o crittografato da All-in-One WP Migration). Esportalo di nuovo senza crittografia.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Questo è un file Duplicator “DupArchive” (.daf). In Duplicator, crea nuovamente il pacchetto con il formato di archiviazione impostato su ZIP, quindi importalo.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Questo backup del database di UpdraftPlus è crittografato. Decrittografalo in UpdraftPlus (oppure disattiva la crittografia del database ed esegui nuovamente il backup), quindi importalo.','Database dump'=>'Dump del database','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s non è un archivio di backup che possiamo leggere (zip, tar, tar.gz, .wpress, .sql o .sql.gz).','Website archive'=>'Archivio del sito web','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s non contiene alcun contenuto WordPress (nessuna cartella wp-content e nessun dump del database).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Questo file .wpress è crittografato o compresso da All-in-One WP Migration. Esportalo nuovamente disattivando crittografia e compressione, quindi importalo.','Other S3-compatible storage'=>'Altro spazio di archiviazione compatibile con S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 o compatibile con S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Impossibile leggere le chiavi di archiviazione su questo sito. Inserisci nuovamente la chiave segreta nella scheda Archiviazione.','This kind of storage is not known.'=>'Questo tipo di archiviazione non è noto.','Choose a kind of storage.'=>'Scegli un tipo di archiviazione.','Enter the bucket name and the access key.'=>'Inserisci il nome del bucket e la chiave di accesso.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Inserisci l\'ID del tuo account Cloudflare (o l\'endpoint R2 completo).','Enter the endpoint address of your storage.'=>'Inserisci l\'indirizzo dell\'endpoint del tuo spazio di archiviazione.','Enter the OAuth client id from your Google Cloud project.'=>'Inserisci l\'OAuth client id dal tuo progetto Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox non ha restituito un token di aggiornamento. Avvia nuovamente la connessione.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox non è collegato. Ricollegalo nella scheda Archiviazione.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google non ha restituito un token di aggiornamento. Rimuovi questo sito dall\'accesso di terze parti del tuo account Google e connettiti di nuovo.','That file is not in Google Drive any more.'=>'Quel file non è più in Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive non è connesso. Riconnettilo nella scheda Archiviazione.','The storage service did not start the upload.'=>'Il servizio di archiviazione non ha avviato il caricamento.','The storage service sent a reply that could not be read.'=>'Il servizio di archiviazione ha inviato una risposta illeggibile.','A temporary backup file could not be read.'=>'Impossibile leggere un file di backup temporaneo.','A deploy link is read-only.'=>'Un link di distribuzione è di sola lettura.','The deploy code has no link for a file this backup needs.'=>'Il codice di distribuzione non contiene alcun collegamento per un file richiesto da questo backup.','The deploy link'=>'Il link di distribuzione']];